const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const northernKenya = ee.Geometry.Polygon([
    [[34, 0], [42, 0], [42, 4.5], [34, 4.5], [34, 0]]
  ]);

  const southernKenya = ee.Geometry.Polygon([
    [[34, -4.5], [42, -4.5], [42, 0], [34, 0], [34, -4.5]]
  ]);

  const startDate = '2019-05-01';
  const endDate = '2019-06-30';

  // 2. Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 3. Data Acquisition for Northern Kenya
  let colNorth = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(northernKenya)
    .filterDate(startDate, endDate)
    .map(maskS2clouds);

  const sizeNorth = colNorth.size().getInfo();
  console.log(`Northern Kenya Images: ${sizeNorth}`);

  if (sizeNorth === 0) {
    // Try Landsat 8 as fallback
    colNorth = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(northernKenya)
      .filterDate(startDate, endDate)
      .map(function(img) {
        const cloudMask = img.select('QA_PIXEL').bitwiseAnd(1 << 3).eq(0);
        return img.updateMask(cloudMask);
      });

    const sizeNorthL8 = colNorth.size().getInfo();
    console.log(`Northern Kenya Landsat Images: ${sizeNorthL8}`);

    if (sizeNorthL8 === 0) {
      console.log('No data for Northern Kenya.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 4. Data Acquisition for Southern Kenya
  let colSouth = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(southernKenya)
    .filterDate(startDate, endDate)
    .map(maskS2clouds);

  const sizeSouth = colSouth.size().getInfo();
  console.log(`Southern Kenya Images: ${sizeSouth}`);

  if (sizeSouth === 0) {
    colSouth = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(southernKenya)
      .filterDate(startDate, endDate)
      .map(function(img) {
        const cloudMask = img.select('QA_PIXEL').bitwiseAnd(1 << 3).eq(0);
        return img.updateMask(cloudMask);
      });

    const sizeSouthL8 = colSouth.size().getInfo();
    console.log(`Southern Kenya Landsat Images: ${sizeSouthL8}`);

    if (sizeSouthL8 === 0) {
      console.log('No data for Southern Kenya.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 5. Calculate NDVI and create composites
  function addNDVI(image) {
    let ndvi;
    if (image.bandNames().contains('B8').getInfo()) {
      // Sentinel-2
      ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    } else {
      // Landsat 8
      ndvi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
    }
    return image.addBands(ndvi);
  }

  const northComposite = colNorth.map(addNDVI).select('NDVI').median();
  const southComposite = colSouth.map(addNDVI).select('NDVI').median();

  // 6. Calculate mean NDVI and pixel counts
  const statsNorth = northComposite.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: northernKenya,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const statsSouth = southComposite.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: southernKenya,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const ndviNorth = statsNorth['NDVI_mean'];
  const countNorth = statsNorth['NDVI_count'];
  const ndviSouth = statsSouth['NDVI_mean'];
  const countSouth = statsSouth['NDVI_count'];

  console.log(`Northern Kenya NDVI: ${ndviNorth}, Pixels: ${countNorth}`);
  console.log(`Southern Kenya NDVI: ${ndviSouth}, Pixels: ${countSouth}`);

  // 7. Validation & Final Answer
  if (countNorth === 0 || countSouth === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (ndviNorth === null || ndviSouth === null || 
      ndviNorth < -1 || ndviNorth > 1 || 
      ndviSouth < -1 || ndviSouth > 1) {
    console.log('Invalid NDVI values.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (ndviNorth < ndviSouth) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
